  rewrittenContent: text("rewritten_content"),
  reviewedAt: timestamp("reviewed_at"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export type DocumentReview = typeof documentReviews.$inferSelect;
export type InsertDocumentReview = typeof documentReviews.$inferInsert;


// ============================================================================
// PHASE 5: ORGANIZATIONAL MEMORY — Cross-Surface Learning + Drift Models
// ============================================================================

/**
 * Cross-Surface Learning — Violation Pattern Tracker
 * 
 * Tracks which violation types recur across different surfaces (website, docs,
 * sales content, etc.) to enable pattern recognition and predictive governance.
 * This is the "learning" layer — the system gets smarter over time.
 */
export const violationPatterns = pgTable("violation_patterns", {
  id: serial("id").primaryKey(),
  patternId: varchar("patternId", { length: 64 }).notNull().unique(),

  // Pattern identification
  violationType: varchar("violationType", { length: 128 }).notNull(),
  surface: varchar("surface", { length: 64 }).notNull(), // website, docs, sales, support, api-docs
  route: varchar("route", { length: 512 }),

  // Recurrence tracking
  firstSeen: timestamp("firstSeen").defaultNow().notNull(),
  lastSeen: timestamp("lastSeen").defaultNow().notNull(),
  occurrenceCount: integer("occurrenceCount").default(1).notNull(),

  // Resolution tracking
  autoFixedCount: integer("autoFixedCount").default(0).notNull(),
  manualFixedCount: integer("manualFixedCount").default(0).notNull(),
  revertedCount: integer("revertedCount").default(0).notNull(),

  // Pattern metadata
  avgSeverity: varchar("avgSeverity", { length: 16 }), // low/medium/high/critical
  commonContent: text("commonContent"), // Sample of recurring violation content
  suggestedPrevention: text("suggestedPrevention"), // AI-generated prevention advice

  // Cross-surface correlation
  relatedPatterns: json("relatedPatterns").$type<string[]>(), // patternIds that co-occur

  createdAt: timestamp("createdAt").defaultNow().notNull(),
  updatedAt: timestamp("updatedAt").defaultNow().notNull(),
});

export type ViolationPattern = typeof violationPatterns.$inferSelect;
export type InsertViolationPattern = typeof violationPatterns.$inferInsert;

