export type AutoApplySeverity = 'low' | 'medium' | 'high' | 'critical';

export interface AutoApplyConfig {
  enabled: boolean;
  maxSeverity: AutoApplySeverity;
  activeProfile: string;
  profileLocked: boolean;
}

/**
 * Narrow a persisted severity to the severity union.
 *
 * `governance_settings.autoApplyMaxSeverity` is a plain varchar column, so the
 * database can hand back any string. Unrecognised values fall back to the same
 * default the column declares ('medium') rather than widening the config type.
 */
function toAutoApplySeverity(
  value: string | null | undefined,
  fallback: AutoApplySeverity = 'medium',
): AutoApplySeverity {
  switch (value) {
    case 'low':
    case 'medium':
    case 'high':
    case 'critical':
      return value;
    default:
      return fallback;
  }
}
